// === Tab: mySketch ===
/**
 * Procedural Abstract Relics — p5.js
 * ---------------------------------
 * Goal: A sleek, stylized, highly diverse generative system inspired by abstract “symbol plates”:
 * rounded frames, triangles, circles, spirals, ribbons, hatching/contours, ink outlines, soft fills.
 *
 * Key requirements implemented:
 * - MANY shapes (typically 80–220 macro shapes + thousands of micro marks).
 * - Exactly 5 base colors per seed (procedural palette generator). Everything derives from those 5.
 * - Extreme seed diversity: layout grammar + palette scheme + pattern families + microstructure.
 * - Build process is dynamic: artwork is constructed over time via a deterministic task queue.
 * - Reseeding logic & controls.
 *
 * Controls:
 * - R : new seed (completely new piece)
 * - Shift+R : rebuild same seed (same piece rebuilt over time)
 * - S : save PNG
 * - Space : pause/resume build
 * - H : toggle HUD
 * - +/- : speed (tasks per frame)
 * - A : toggle gentle “afterbuild” shimmer
 *
 * Paste into the p5.js editor (https://editor.p5js.org/) and run.
 *
 * Notes:
 * - This is intentionally a big system. It’s “deep” through modularity + variation,
 *   not through pointless bloat. Still, it’s lengthy by design.
 */

/* =========================================================
   Global Config
   ========================================================= */

let W, H, D;
let gBG, gFILL, gINK, gFX;   // layered buffers
let scene;
let hud = true;
let paused = false;
let afterShimmer = true;

let TASKS_PER_FRAME = 140;   // speed knob (higher = faster build)
let MAX_CANVAS = 980;

let SEED = 0;
let rng;                     // deterministic RNG for the entire scene
let palette;                 // 5 base colors
let blueprint;               // layout + style decisions

// paper/texture caches
let paperTex;
let grainTex;

// used for deterministic per-frame shimmer without calling random()
let shimmerT = 0;

/* =========================================================
   p5 Setup / Draw
   ========================================================= */

function setup() {
  D = pixelDensity();
  pixelDensity(1); // keep consistent & fast
  setCanvasSize();

  initBuffers();
  newSeed(true); // new piece on load

  // crisp-ish but still organic
  drawingContext.lineJoin = "round";
  drawingContext.lineCap = "round";
}

function windowResized() {
  setCanvasSize();
  initBuffers();
  rebuildSameSeed(); // keep piece consistent after resize
}

function setCanvasSize() {
  let s = min(MAX_CANVAS, max(windowWidth, windowHeight));
  W = floor(s);
  H = floor(s);
  resizeCanvas(W, H);
}

function initBuffers() {
  gBG   = createGraphics(W, H);
  gFILL = createGraphics(W, H);
  gINK  = createGraphics(W, H);
  gFX   = createGraphics(W, H);

  for (let g of [gBG, gFILL, gINK, gFX]) {
    g.pixelDensity(1);
    g.clear();
    g.drawingContext.lineJoin = "round";
    g.drawingContext.lineCap = "round";
  }

  paperTex = makePaperTexture(W, H);
  grainTex = makeGrainTexture(W, H);
}

function draw() {
  background(245);

  if (!paused && scene) {
    // build progress in chunks each frame
    scene.step(TASKS_PER_FRAME);
  }

  // composite
  image(gBG, 0, 0);
  image(gFILL, 0, 0);
  image(gINK, 0, 0);

  // post FX / overlay
  compositeFX();

  // HUD
  if (hud) drawHUD();

  // if the scene is done, optionally keep subtle motion
  if (scene && scene.done && afterShimmer && !paused) {
    shimmerT += 1;
  }
}

/* =========================================================
   FX Compositing
   ========================================================= */

function compositeFX() {
  // base: subtle vignette + paper
  gFX.clear();

  // Paper
  gFX.push();
  gFX.blendMode(BLEND);
  gFX.tint(255, 140);
  gFX.image(paperTex, 0, 0);
  gFX.pop();

  // Vignette
  gFX.push();
  gFX.noFill();
  let steps = 24;
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let a = 50 * pow(t, 2.2);
    gFX.stroke(20, a);
    gFX.strokeWeight(2);
    let m = lerp(10, min(W, H) * 0.22, t);
    gFX.rect(m, m, W - 2 * m, H - 2 * m, lerp(10, 80, t));
  }
  gFX.pop();

  // Deterministic shimmer grain overlay
  if (scene && scene.done && afterShimmer) {
    let alpha = 18;
    let phase = hashFloat(SEED ^ 0x9e3779b9, shimmerT);
    gFX.push();
    gFX.translate(W / 2, H / 2);
    gFX.rotate((phase - 0.5) * 0.02);
    gFX.scale(1.0 + (phase - 0.5) * 0.01);
    gFX.translate(-W / 2, -H / 2);
    gFX.tint(255, alpha);
    gFX.blendMode(MULTIPLY);
    gFX.image(grainTex, 0, 0);
    gFX.pop();
  } else {
    // build-time grain: a touch stronger
    gFX.push();
    gFX.tint(255, 28);
    gFX.blendMode(MULTIPLY);
    gFX.image(grainTex, 0, 0);
    gFX.pop();
  }

  image(gFX, 0, 0);
}

/* =========================================================
   HUD
   ========================================================= */

function drawHUD() {
  push();
  noStroke();
  fill(20, 160);
  rect(12, 12, 270, 96, 14);

  fill(250);
  textFont("monospace");
  textSize(12);
  let lines = [
    `SEED: ${SEED >>> 0}`,
    `TASKS/FRAME: ${TASKS_PER_FRAME}`,
    `PROGRESS: ${scene ? nf(scene.progress() * 100, 2, 1) + "%" : "-"}`,
    `DONE: ${scene ? scene.done : "-"}`,
    `R new | Shift+R rebuild | +/- speed | Space pause`,
    `S save | H HUD | A shimmer`
  ];
  let y = 32;
  for (let i = 0; i < lines.length; i++) {
    text(lines[i], 24, y);
    y += 14;
  }
  pop();

  // palette swatches
  if (palette) {
    push();
    let x = 300, y2 = 20;
    for (let i = 0; i < 5; i++) {
      fill(palette.cols[i]);
      stroke(0, 60);
      strokeWeight(1);
      rect(x + i * 22, y2, 18, 18, 4);
    }
    pop();
  }
}

/* =========================================================
   Controls
   ========================================================= */

function keyPressed() {
  if (key === "r") newSeed(true);
  if (key === "R") rebuildSameSeed();

  if (key === " ") paused = !paused;
  if (key === "h" || key === "H") hud = !hud;

  if (key === "s" || key === "S") saveCanvas(`abstract-relic_${SEED >>> 0}`, "png");

  if (key === "+" || key === "=") TASKS_PER_FRAME = min(800, TASKS_PER_FRAME + 40);
  if (key === "-" || key === "_") TASKS_PER_FRAME = max(10, TASKS_PER_FRAME - 40);

  if (key === "a" || key === "A") afterShimmer = !afterShimmer;
}

/* =========================================================
   Seeding / Scene Creation
   ========================================================= */

function newSeed(resetTimeEntropy = true) {
  // time + mouse + frameCount hashed -> 32-bit seed
  var t = resetTimeEntropy ? (Date.now() & 0xffffffff) : (SEED >>> 0);
  let mixed = mixBits32(t ^ (((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + 1) * 374761393) ^ (((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + 7) * 668265263) ^ (frameCount * 1442695041));
  SEED = mixed >>> 0;
  rebuildSameSeed();
}

function rebuildSameSeed() {
  rng = new RNG(SEED);
  noiseSeed(SEED ^ 0xA5A5A5A5);

  palette = new Palette(rng);
  blueprint = new Blueprint(rng, palette);

  clearAllBuffers();

  scene = new Scene(rng, palette, blueprint);
  scene.build();

  paused = false;
  shimmerT = 0;
}

function clearAllBuffers() {
  for (let g of [gBG, gFILL, gINK, gFX]) g.clear();
}

/* =========================================================
   Blueprint: macro decisions that strongly separate seeds
   ========================================================= */

class Blueprint {
  constructor(rng, palette) {
    this.rng = rng;
    this.palette = palette;

    // Macro composition style families (very different)
    this.layoutMode = rng.pick([
      "packed", "gridJitter", "orbitals", "diagonalBands", "clusters", "totemColumns", "ringGarden"
    ], [1.2, 1.0, 0.9, 0.9, 1.1, 0.8, 0.8]);

    // Density & scale distribution
    this.shapeCount = floor(rng.range(85, 220) * rng.range(0.85, 1.15));
    this.bigShapeBias = rng.range(0.12, 0.35); // chance of large heroes

    // Stylistic toggles
    this.outlineStyle = rng.pick(["clean", "double", "wobbleFine", "wobbleBold"], [1.2, 0.9, 0.9, 0.7]);
    this.hatchFamily = rng.pick(["contours", "hatch", "moire", "stipples", "topo"], [1.0, 1.2, 0.8, 0.7, 0.9]);
    this.fillFamily = rng.pick(["softGradient", "banded", "inkWash", "cellShade", "marble"], [1.2, 0.9, 0.8, 0.7, 0.8]);

    // Background style
    this.bgMode = rng.pick(["paperGlow", "mistyBands", "radialFog", "splitTone", "grainyFlat"], [1.1, 0.9, 0.9, 0.8, 0.8]);

    // Internal motif bias (spirals/ribbons/frames etc.)
    this.motifBias = {
      spiral: rng.range(0.08, 0.28),
      ribbon: rng.range(0.10, 0.30),
      frame:  rng.range(0.10, 0.30),
      lens:   rng.range(0.08, 0.22),
      wedge:  rng.range(0.08, 0.22),
      orb:    rng.range(0.10, 0.28),
      glyph:  rng.range(0.10, 0.25),
    };

    // A “signature” micro-style that changes line weights, offsets, etc.
    this.inkWeight = rng.range(0.65, 1.55);
    this.detailLevel = rng.range(0.7, 1.4);

    // Edge margin
    this.margin = rng.range(0.06, 0.12) * min(W, H);

    // Post vibes
    this.shadowMode = rng.bool(0.72);
    this.microScratches = rng.bool(0.58);

    // Deterministic “extra spice” values
    this.flowScale = rng.range(0.002, 0.01);
    this.flowStrength = rng.range(0.35, 1.2);
  }
}

/* =========================================================
   Scene: task queue orchestration
   ========================================================= */

class Scene {
  constructor(rng, palette, blueprint) {
    this.rng = rng;
    this.palette = palette;
    this.blueprint = blueprint;

    this.queue = new TaskQueue();
    this.entities = [];
    this.done = false;

    this.totalTasks = 0;
    this.finishedTasks = 0;

    // placement caches
    this.anchors = [];
  }

  build() {
    // 1) Background tasks
    this.enqueueBackground();

    // 2) Generate anchor points (layout)
    this.anchors = generateAnchors(this.rng, this.blueprint);

    // 3) Create entities from anchors
    this.entities = generateEntities(this.rng, this.palette, this.blueprint, this.anchors);

    // 4) Enqueue build tasks for each entity
    for (let e of this.entities) {
      e.enqueue(this.queue);
    }

    // 5) Final overlay tasks (scratches, accents, unify)
    this.enqueueFinisher();

    this.totalTasks = this.queue.size();
    this.finishedTasks = 0;
    this.done = false;
  }

  step(budget) {
    var steps = 0;
    while (steps < budget && this.queue.size() > 0) {
      let task = this.queue.peek();
      let finished = task.step();
      if (finished) {
        this.queue.pop();
        this.finishedTasks++;
      }
      steps++;
    }
    if (this.queue.size() === 0) this.done = true;
  }

  progress() {
    if (this.totalTasks <= 0) return 0;
    return constrain(this.finishedTasks / this.totalTasks, 0, 1);
  }

  enqueueBackground() {
    let bp = this.blueprint;

    // background “plate” is built gradually: gradient + fog + subtle patterns
    this.queue.push(makeTask_BG_Base(bp, this.palette, this.rng));
    this.queue.push(makeTask_BG_Secondary(bp, this.palette, this.rng));
    this.queue.push(makeTask_BG_Speckles(bp, this.palette, this.rng));
  }

  enqueueFinisher() {
    var bp = this.blueprint;

    if (bp.microScratches) {
      this.queue.push(makeTask_Overlay_Scratches(bp, this.palette, this.rng));
    }
    this.queue.push(makeTask_Overlay_Unify(bp, this.palette, this.rng));
  }
}

/* =========================================================
   Task Queue
   ========================================================= */

class TaskQueue {
  constructor() {
    this.arr = [];
  }
  push(task) { this.arr.push(task); }
  pop() { return this.arr.shift(); }
  peek() { return this.arr[0]; }
  size() { return this.arr.length; }
}

/* =========================================================
   Deterministic RNG (Mulberry32-ish)
   ========================================================= */

class RNG {
  constructor(seed) {
    this.s = seed >>> 0;
  }
  nextU32() {
    // xorshift-like mix
    var t = this.s += 0x6D2B79F5;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0);
  }
  float() {
    return this.nextU32() / 4294967296;
  }
  range(a, b) {
    return a + (b - a) * this.float();
  }
  int(a, b) {
    // inclusive
    return floor(this.range(a, b + 1));
  }
  bool(p = 0.5) {
    return this.float() < p;
  }
  pick(arr, weights = null) {
    if (!weights) return arr[this.int(0, arr.length - 1)];
    let sum = 0;
    for (let w of weights) sum += w;
    let r = this.float() * sum;
    let acc = 0;
    for (let i = 0; i < arr.length; i++) {
      acc += weights[i];
      if (r <= acc) return arr[i];
    }
    return arr[arr.length - 1];
  }
  shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      let j = this.int(0, i);
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }
}

/* =========================================================
   Palette (5 base colors, procedural scheme)
   ========================================================= */

class Palette {
  constructor(rng) {
    this.rng = rng;

    // Choose scheme family
    this.scheme = rng.pick(
      ["analogous", "complement", "triad", "splitComp", "tetrad", "monoAccent"],
      [1.2, 0.9, 0.8, 0.9, 0.7, 0.9]
    );

    // Base hue & parameters
    this.baseHue = rng.range(0, 360);
    this.satBase = rng.range(38, 72);
    this.litBase = rng.range(42, 70);

    // produce exactly 5 colors
    this.cols = this.makeFive();
  }

  makeFive() {
    var r = this.rng;
    let hues = [];

    const H = (x) => (x % 360 + 360) % 360;

    if (this.scheme === "analogous") {
      let spread = r.range(18, 55);
      hues = [
        H(this.baseHue - spread),
        H(this.baseHue - spread * 0.35),
        H(this.baseHue),
        H(this.baseHue + spread * 0.4),
        H(this.baseHue + spread)
      ];
    } else if (this.scheme === "complement") {
      let comp = H(this.baseHue + 180);
      hues = [
        H(this.baseHue - r.range(8, 30)),
        H(this.baseHue + r.range(0, 24)),
        H(this.baseHue + r.range(10, 36)),
        H(comp - r.range(10, 28)),
        H(comp + r.range(6, 26))
      ];
    } else if (this.scheme === "triad") {
      let h2 = H(this.baseHue + 120);
      let h3 = H(this.baseHue + 240);
      hues = [H(this.baseHue), H(this.baseHue + r.range(10, 28)), H(h2), H(h3), H(h3 + r.range(-18, 18))];
    } else if (this.scheme === "splitComp") {
      let c = H(this.baseHue + 180);
      hues = [H(this.baseHue), H(this.baseHue + r.range(12, 38)), H(c - r.range(18, 45)), H(c + r.range(18, 45)), H(this.baseHue - r.range(10, 34))];
    } else if (this.scheme === "tetrad") {
      var h2 = H(this.baseHue + 90);
      var h3 = H(this.baseHue + 180);
      let h4 = H(this.baseHue + 270);
      hues = [H(this.baseHue), H(h2), H(h3), H(h4), H(this.baseHue + r.range(-25, 25))];
    } else { // monoAccent
      let accent = H(this.baseHue + r.pick([120, 150, 180, 210], [0.8, 0.9, 1.1, 0.8]));
      hues = [H(this.baseHue - 10), H(this.baseHue + 6), H(this.baseHue + 18), H(this.baseHue - 22), accent];
    }

    // derive sat/lit per color, but still feels cohesive
    let cols = [];
    for (let i = 0; i < 5; i++) {
      var s = constrain(this.satBase + r.range(-14, 14) + (i === 4 ? r.range(0, 12) : 0), 22, 86);
      let l = constrain(this.litBase + r.range(-18, 18) + (i === 0 ? -8 : 0) + (i === 2 ? 6 : 0), 22, 85);
      cols.push(hslColor(hues[i], s, l));
    }
    return cols;
  }

  pick(i) {
    return this.cols[((i % 5) + 5) % 5];
  }

  // deterministic weighted pick for accents
  accent(rng) {
    return this.cols[rng.pick([0, 1, 2, 3, 4], [0.9, 1.0, 1.2, 0.9, 1.3])];
  }

  // “ink” / dark derived (still from base)
  ink() {
    // choose the darkest-ish base then push darker
    let best = this.cols[0];
    let bestL = 999;
    for (let c of this.cols) {
      let hl = approxLightness(c);
      if (hl < bestL) { bestL = hl; best = c; }
    }
    // return a slightly deepened version
    return lerpColor(color(0, 0, 0), best, 0.45);
  }
}

/* =========================================================
   Entity System
   ========================================================= */

class Entity {
  constructor(rng, palette, bp, x, y, s, rot) {
    this.rng = rng;
    this.palette = palette;
    this.bp = bp;

    this.x = x;
    this.y = y;
    this.s = s;
    this.rot = rot;

    this.fillA = palette.accent(rng);
    this.fillB = palette.accent(rng);
    this.strokeC = palette.ink();

    this.layer = rng.pick(["mid", "top"], [1.2, 0.8]);
    this.kind = "base";

    // style knobs
    this.outlineW = bp.inkWeight * rng.range(0.8, 1.4);
    this.detail = bp.detailLevel * rng.range(0.7, 1.35);

    // bounding radius for simple overlap checks
    this.boundR = s * rng.range(0.55, 0.85);
  }

  enqueue(queue) {
    // override in subclasses
  }
}

/* =========================================================
   Specific Entity Types (many)
   ========================================================= */

/**
 * Rounded Plate — like a soft rectangle with inner frames & hatch/contours
 */
class RoundedPlate extends Entity {
  constructor(rng, palette, bp, x, y, s, rot) {
    super(rng, palette, bp, x, y, s, rot);
    this.kind = "RoundedPlate";
    this.w = s * rng.range(0.9, 1.5);
    this.h = s * rng.range(0.7, 1.3);
    this.r = min(this.w, this.h) * rng.range(0.18, 0.36);

    this.frameCount = rng.int(1, rng.bool(0.35) ? 4 : 3);
    this.inset = rng.range(0.06, 0.16) * min(this.w, this.h);

    this.innerMotif = rng.pick(["hatch", "contours", "moire", "spiral", "glyph"], [1.1, 1.0, 0.8, 0.7, 0.9]);
    this.cornerOrbs = rng.bool(0.55);
  }

  enqueue(queue) {
    const params = this.snapshot();
    queue.push(makeTask_Shape_Fill_RoundedPlate(params));
    queue.push(makeTask_Shape_Outline_RoundedPlate(params));
    queue.push(makeTask_Shape_InnerFrames(params));

    if (params.cornerOrbs) queue.push(makeTask_Shape_CornerOrbs(params));
    queue.push(makeTask_Shape_InteriorPattern(params));
  }

  snapshot() {
    return {
      kind: this.kind,
      x: this.x, y: this.y, rot: this.rot,
      w: this.w, h: this.h, r: this.r,
      frameCount: this.frameCount,
      inset: this.inset,
      innerMotif: this.innerMotif,
      cornerOrbs: this.cornerOrbs,
      fillA: this.fillA, fillB: this.fillB,
      strokeC: this.strokeC,
      outlineW: this.outlineW,
      detail: this.detail,
      bp: this.bp,
      seed: SEED
    };
  }
}

/**
 * Tri Wedge — stylized triangle with “eye” bands / contour lines
 */
class TriWedge extends Entity {
  constructor(rng, palette, bp, x, y, s, rot) {
    super(rng, palette, bp, x, y, s, rot);
    this.kind = "TriWedge";
    this.r1 = s * rng.range(0.95, 1.55);
    this.r2 = s * rng.range(0.80, 1.35);
    this.twist = rng.range(-0.35, 0.35);
    this.bandCount = rng.int(10, floor(28 * this.detail));
    this.eye = rng.bool(0.62);
    this.eyeScale = rng.range(0.12, 0.32);
  }

  enqueue(queue) {
    const p = this.snapshot();
    queue.push(makeTask_Shape_Fill_TriWedge(p));
    queue.push(makeTask_Shape_Outline_TriWedge(p));
    queue.push(makeTask_Shape_Bands_TriWedge(p));
    if (p.eye) queue.push(makeTask_Shape_Eye_TriWedge(p));
  }

  snapshot() {
    return {
      kind: this.kind,
      x: this.x, y: this.y, rot: this.rot,
      r1: this.r1, r2: this.r2,
      twist: this.twist,
      bandCount: this.bandCount,
      eye: this.eye,
      eyeScale: this.eyeScale,
      fillA: this.fillA, fillB: this.fillB,
      strokeC: this.strokeC,
      outlineW: this.outlineW,
      detail: this.detail,
      bp: this.bp,
      seed: SEED
    };
  }
}

/**
 * Orb Lens — circle/ellipse with nested arcs & contour rings
 */
class OrbLens extends Entity {
  constructor(rng, palette, bp, x, y, s, rot) {
    super(rng, palette, bp, x, y, s, rot);
    this.kind = "OrbLens";
    this.rx = s * rng.range(0.75, 1.35);
    this.ry = s * rng.range(0.75, 1.35);
    this.rings = rng.int(12, floor(50 * this.detail));
    this.slant = rng.range(-0.55, 0.55);
    this.highlight = rng.bool(0.8);
    this.notch = rng.bool(0.32);
  }

  enqueue(queue) {
    var p = this.snapshot();
    queue.push(makeTask_Shape_Fill_OrbLens(p));
    queue.push(makeTask_Shape_Outline_OrbLens(p));
    queue.push(makeTask_Shape_Rings_OrbLens(p));
    if (p.highlight) queue.push(makeTask_Shape_Highlight_OrbLens(p));
    if (p.notch) queue.push(makeTask_Shape_Notch_OrbLens(p));
  }

  snapshot() {
    return {
      kind: this.kind,
      x: this.x, y: this.y, rot: this.rot,
      rx: this.rx, ry: this.ry,
      rings: this.rings,
