/* =========================================================
   Anchor / Layout Generation
   ========================================================= */

function generateAnchors(rng, bp) {
  let anchors = [];
  var m = bp.margin;
  let bounds = { x0: m, y0: m, x1: W - m, y1: H - m };

  if (bp.layoutMode === "packed") {
    anchors = circlePackingAnchors(rng, bp, bounds);
  } else if (bp.layoutMode === "gridJitter") {
    anchors = gridJitterAnchors(rng, bp, bounds);
  } else if (bp.layoutMode === "orbitals") {
    anchors = orbitalAnchors(rng, bp, bounds);
  } else if (bp.layoutMode === "diagonalBands") {
    anchors = diagonalBandAnchors(rng, bp, bounds);
  } else if (bp.layoutMode === "clusters") {
    anchors = clusteredAnchors(rng, bp, bounds);
  } else if (bp.layoutMode === "totemColumns") {
    anchors = totemAnchors(rng, bp, bounds);
  } else {
    anchors = ringGardenAnchors(rng, bp, bounds);
  }

  // strong shuffle to avoid deterministic ordering artifacts
  rng.shuffle(anchors);

  // clamp count and re-jitter slightly
  let target = bp.shapeCount;
  anchors = anchors.slice(0, target);
  for (let a of anchors) {
    a.x += rng.range(-4, 4);
    a.y += rng.range(-4, 4);
  }
  return anchors;
}

function circlePackingAnchors(rng, bp, bounds) {
  var anchors = [];
  let tries = 9000;
  let maxN = floor(bp.shapeCount * rng.range(1.1, 1.5));

  // variable radii — some large heroes
  let radii = [];
  for (let i = 0; i < maxN; i++) {
    let isHero = rng.bool(bp.bigShapeBias);
    var rr = (isHero ? rng.range(70, 150) : rng.range(26, 78)) * (min(W, H) / 900);
    radii.push(rr);
  }
  radii.sort((a, b) => b - a);

  let placed = [];
  for (let i = 0; i < radii.length; i++) {
    var r = radii[i];
    let ok = false;
    var best = null;
    let bestScore = -1e9;

    for (let t = 0; t < tries; t++) {
      var x = rng.range(bounds.x0 + r, bounds.x1 - r);
      var y = rng.range(bounds.y0 + r, bounds.y1 - r);

      // reject if close to others
      let good = true;
      let score = 0;
      for (let p of placed) {
        let dx = x - p.x, dy = y - p.y;
        let d2 = dx * dx + dy * dy;
        let minD = (r + p.r) * rng.range(0.95, 1.15);
        if (d2 < minD * minD) { good = false; break; }
        score += sqrt(d2); // spread out
      }
      if (good) {
        ok = true;
        if (score > bestScore) { bestScore = score; best = { x, y, r }; }
      }
    }
    if (ok && best) placed.push(best);
    if (placed.length >= maxN * 0.92) break;
  }

  // convert to anchors (size from radius)
  for (let p of placed) {
    anchors.push({
      x: p.x,
      y: p.y,
      s: p.r * rng.range(0.95, 1.4),
      rot: rng.range(-PI, PI)
    });
  }
  return anchors;
}

function gridJitterAnchors(rng, bp, bounds) {
  var anchors = [];
  var cols = rng.int(6, 12);
  let rows = rng.int(6, 12);
  let gx = (bounds.x1 - bounds.x0) / cols;
  let gy = (bounds.y1 - bounds.y0) / rows;

  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      var x = bounds.x0 + (i + 0.5) * gx + rng.range(-0.35, 0.35) * gx;
      var y = bounds.y0 + (j + 0.5) * gy + rng.range(-0.35, 0.35) * gy;

      // multiple anchors per cell sometimes
      let count = rng.pick([1, 1, 1, 2, 2, 3], [1.2, 1.2, 1.2, 0.8, 0.7, 0.3]);
      for (let k = 0; k < count; k++) {
        anchors.push({
          x: x + rng.range(-0.22, 0.22) * gx,
          y: y + rng.range(-0.22, 0.22) * gy,
          s: min(gx, gy) * rng.range(0.35, 0.95),
          rot: rng.range(-PI, PI)
        });
      }
    }
  }
  return anchors;
}

function orbitalAnchors(rng, bp, bounds) {
  var anchors = [];
  let cx = (bounds.x0 + bounds.x1) * 0.5;
  let cy = (bounds.y0 + bounds.y1) * 0.5;

  let rings = rng.int(3, 7);
  for (let r = 0; r < rings; r++) {
    var rr = lerp(min(W, H) * 0.10, min(W, H) * 0.42, (r + 0.2) / rings) * rng.range(0.9, 1.1);
    var n = rng.int(8, 22);
    for (let i = 0; i < n; i++) {
      var a = (i / n) * TAU + rng.range(-0.15, 0.15) + r * rng.range(-0.12, 0.12);
      var x = cx + cos(a) * rr * rng.range(0.92, 1.06);
      var y = cy + sin(a) * rr * rng.range(0.92, 1.06);
      anchors.push({
        x, y,
        s: min(W, H) * rng.range(0.04, 0.12),
        rot: a + rng.range(-0.6, 0.6)
      });
    }
  }

  // a few center heroes
  let heroes = rng.int(3, 8);
  for (let i = 0; i < heroes; i++) {
    anchors.push({
      x: cx + rng.range(-80, 80),
      y: cy + rng.range(-80, 80),
      s: min(W, H) * rng.range(0.10, 0.18),
      rot: rng.range(-PI, PI)
    });
  }
  return anchors;
}

function diagonalBandAnchors(rng, bp, bounds) {
  var anchors = [];
  let bands = rng.int(4, 8);
  let angle = rng.range(-0.9, -0.45);
  let dir = createVector(cos(angle), sin(angle));
  let perp = createVector(-dir.y, dir.x);

  let span = dist(bounds.x0, bounds.y0, bounds.x1, bounds.y1);
  for (let b = 0; b < bands; b++) {
    var t = (b + 0.5) / bands;
    let offset = lerp(-span * 0.3, span * 0.3, t) + rng.range(-30, 30);

    let bandN = rng.int(18, 44);
    for (let i = 0; i < bandN; i++) {
      let along = lerp(-span * 0.7, span * 0.7, (i + rng.float()) / bandN);
      var x = (W / 2) + dir.x * along + perp.x * offset + rng.range(-18, 18);
      var y = (H / 2) + dir.y * along + perp.y * offset + rng.range(-18, 18);
      if (x < bounds.x0 || x > bounds.x1 || y < bounds.y0 || y > bounds.y1) continue;
      anchors.push({
        x, y,
        s: min(W, H) * rng.range(0.035, 0.12) * rng.range(0.9, 1.25),
        rot: angle + rng.range(-0.9, 0.9)
      });
    }
  }
  return anchors;
}

function clusteredAnchors(rng, bp, bounds) {
  var anchors = [];
  let clusters = rng.int(3, 7);
  let centers = [];
  for (let i = 0; i < clusters; i++) {
    centers.push({
      x: rng.range(bounds.x0, bounds.x1),
      y: rng.range(bounds.y0, bounds.y1),
      spread: rng.range(60, 220) * (min(W, H) / 900)
    });
  }
  for (let c of centers) {
    var n = rng.int(20, 60);
    for (let i = 0; i < n; i++) {
      var a = rng.range(0, TAU);
      var rr = abs(rng.range(0, 1) - rng.range(0, 1)) * c.spread; // bias toward center
      var x = c.x + cos(a) * rr + rng.range(-10, 10);
      var y = c.y + sin(a) * rr + rng.range(-10, 10);
      if (x < bounds.x0 || x > bounds.x1 || y < bounds.y0 || y > bounds.y1) continue;
      anchors.push({
        x, y,
        s: min(W, H) * rng.range(0.03, 0.14) * rng.range(0.8, 1.35),
        rot: rng.range(-PI, PI)
      });
    }
  }
  // add a few inter-cluster bridges
  let bridges = rng.int(18, 44);
  for (let i = 0; i < bridges; i++) {
    anchors.push({
      x: rng.range(bounds.x0, bounds.x1),
      y: rng.range(bounds.y0, bounds.y1),
      s: min(W, H) * rng.range(0.03, 0.08),
      rot: rng.range(-PI, PI)
    });
  }
  return anchors;
}

function totemAnchors(rng, bp, bounds) {
  var anchors = [];
  var cols = rng.int(3, 6);
  for (let c = 0; c < cols; c++) {
    var x = lerp(bounds.x0, bounds.x1, (c + 0.5) / cols) + rng.range(-18, 18);
    var n = rng.int(18, 46);
    for (let i = 0; i < n; i++) {
      var y = lerp(bounds.y0, bounds.y1, (i + 0.5) / n) + rng.range(-28, 28);
      anchors.push({
        x: x + rng.range(-30, 30),
        y: y,
        s: min(W, H) * rng.range(0.035, 0.15) * rng.range(0.85, 1.25),
        rot: rng.range(-0.35, 0.35)
      });
    }
  }
  return anchors;
}

function ringGardenAnchors(rng, bp, bounds) {
  var anchors = [];
  var cx = (bounds.x0 + bounds.x1) * 0.5;
  var cy = (bounds.y0 + bounds.y1) * 0.5;

  let petals = rng.int(9, 18);
  let ringR = min(W, H) * rng.range(0.22, 0.36);
  for (let i = 0; i < petals; i++) {
    var a = (i / petals) * TAU + rng.range(-0.12, 0.12);
    var x = cx + cos(a) * ringR * rng.range(0.92, 1.08);
    var y = cy + sin(a) * ringR * rng.range(0.92, 1.08);
    anchors.push({ x, y, s: min(W, H) * rng.range(0.07, 0.16), rot: a + rng.range(-0.7, 0.7) });

    // sub-anchors around each petal
    let sub = rng.int(5, 14);
    for (let k = 0; k < sub; k++) {
      let aa = a + rng.range(-0.55, 0.55);
      var rr = rng.range(26, 110) * (min(W, H) / 900);
      anchors.push({
        x: x + cos(aa) * rr,
        y: y + sin(aa) * rr,
        s: min(W, H) * rng.range(0.03, 0.09),
        rot: aa + rng.range(-1.0, 1.0)
      });
    }
  }

  // core cluster
  let core = rng.int(30, 80);
  for (let i = 0; i < core; i++) {
    anchors.push({
      x: cx + rng.range(-120, 120),
      y: cy + rng.range(-120, 120),
      s: min(W, H) * rng.range(0.03, 0.11),
      rot: rng.range(-PI, PI)
    });
  }
  return anchors;
}

/* =========================================================
   Entity Generation
   ========================================================= */

function generateEntities(rng, palette, bp, anchors) {
  let entities = [];
  let kindPool = buildKindPool(bp);

  // A lightweight overlap filter: keep a subset if too dense
  // (but still allow overlaps sometimes for richness)
  var placed = [];
  for (let a of anchors) {
    let kind = rng.pick(kindPool.kinds, kindPool.weights);

    var s = a.s * rng.range(0.75, 1.25);
    // hero shapes occasionally
    if (rng.bool(bp.bigShapeBias)) s *= rng.range(1.15, 1.8);

    let e = makeEntity(kind, rng, palette, bp, a.x, a.y, s, a.rot);

    // overlap check
    var ok = true;
    let allowOverlap = rng.bool(0.18);
    if (!allowOverlap) {
      for (let p of placed) {
        var dx = e.x - p.x, dy = e.y - p.y;
        var d2 = dx * dx + dy * dy;
        var minD = (e.boundR + p.r) * 0.92;
        if (d2 < minD * minD) { ok = false; break; }
      }
    }

    if (ok) {
      entities.push(e);
      placed.push({ x: e.x, y: e.y, r: e.boundR });
    }
    if (entities.length >= bp.shapeCount) break;
  }

  // add a few micro-entities (small glyph disks etc.) for density
  let microN = floor(bp.shapeCount * rng.range(0.25, 0.55));
  for (let i = 0; i < microN; i++) {
    var x = rng.range(bp.margin, W - bp.margin);
    var y = rng.range(bp.margin, H - bp.margin);
    var s = min(W, H) * rng.range(0.018, 0.05);
    let rot = rng.range(-PI, PI);

    var kind = rng.pick(["GlyphDisk", "OrbLens", "TriWedge"], [1.2, 0.9, 0.7]);
    var e = makeEntity(kind, rng, palette, bp, x, y, s, rot);
    entities.push(e);
  }

  // reorder by layer-like depth: mid first then top
  entities.sort((a, b) => (a.layer < b.layer ? -1 : 1));
  return entities;
}

function buildKindPool(bp) {
  // derive weights from motifBias but keep variety
  let kinds = [
    "RoundedPlate",
    "TriWedge",
    "OrbLens",
    "SpiralShell",
    "RibbonKnot",
    "FramedWindow",
    "GlyphDisk"
  ];

  // weights tuned per blueprint (adds huge diversity)
  let w = [];
  for (let k of kinds) {
    if (k === "SpiralShell") w.push(0.7 + bp.motifBias.spiral * 2.6);
    else if (k === "RibbonKnot") w.push(0.7 + bp.motifBias.ribbon * 2.8);
    else if (k === "FramedWindow") w.push(0.8 + bp.motifBias.frame * 2.6);
    else if (k === "OrbLens") w.push(0.8 + bp.motifBias.lens * 2.2);
    else if (k === "TriWedge") w.push(0.8 + bp.motifBias.wedge * 2.2);
    else if (k === "GlyphDisk") w.push(0.9 + bp.motifBias.glyph * 2.0);
    else w.push(1.1);
  }

  // normalize-ish (not strictly needed)
  return { kinds, weights: w };
}

function makeEntity(kind, rng, palette, bp, x, y, s, rot) {
  if (kind === "RoundedPlate") return new RoundedPlate(rng, palette, bp, x, y, s, rot);
  if (kind === "TriWedge") return new TriWedge(rng, palette, bp, x, y, s, rot);
  if (kind === "OrbLens") return new OrbLens(rng, palette, bp, x, y, s, rot);
  if (kind === "SpiralShell") return new SpiralShell(rng, palette, bp, x, y, s, rot);
  if (kind === "RibbonKnot") return new RibbonKnot(rng, palette, bp, x, y, s, rot);
  if (kind === "FramedWindow") return new FramedWindow(rng, palette, bp, x, y, s, rot);
  return new GlyphDisk(rng, palette, bp, x, y, s, rot);
}

/* =========================================================
   Background Tasks
   ========================================================= */

function makeTask_BG_Base(bp, pal, rng) {
  // draw background gradually in bands
  let mode = bp.bgMode;
  var y = 0;
  let step = 10; // scanline chunk height
  let ink = pal.ink();

  // precompute parameters
  let h0 = rng.range(0, 360);
  let fogC = pal.pick(rng.int(0, 4));
  let fogC2 = pal.pick(rng.int(0, 4));
  let blend = rng.pick([0.18, 0.26, 0.32, 0.38], [1.0, 1.1, 0.8, 0.6]);

  return {
    step: () => {
      gBG.push();
      gBG.noStroke();

      for (let k = 0; k < 1; k++) {
        if (y >= H) break;

        // choose background palette based on mode
        if (mode === "paperGlow") {
          var t = y / (H - 1);
          let c1 = lerpColor(color(248, 245, 240), fogC, 0.18);
          let c2 = lerpColor(color(252, 250, 247), fogC2, 0.14);
          var c = lerpColor(c1, c2, smoothstep(0, 1, t));
          gBG.fill(red(c), green(c), blue(c), 255);
        } else if (mode === "mistyBands") {
          var t = y / (H - 1);
          let band = 0.5 + 0.5 * sin(t * TAU * rng.pick([1, 2, 3, 4], [0.8, 1.0, 0.7, 0.5]) + h0);
          var c = lerpColor(lerpColor(color(250, 246, 240), fogC, 0.22), fogC2, band * 0.18);
          gBG.fill(red(c), green(c), blue(c), 255);
        } else if (mode === "radialFog") {
          var t = y / (H - 1);
          // base is neutral
          var c = lerpColor(color(248, 246, 242), fogC, 0.12);
          gBG.fill(red(c), green(c), blue(c), 255);
        } else if (mode === "splitTone") {
          var t = y / (H - 1);
          let cA = lerpColor(color(248, 245, 241), fogC, 0.18);
          let cB = lerpColor(color(248, 245, 241), fogC2, 0.18);
          var w = smoothstep(0.25, 0.75, t);
          var c = lerpColor(cA, cB, w);
          gBG.fill(red(c), green(c), blue(c), 255);
        } else {
          // grainyFlat
          var c = lerpColor(color(248, 246, 242), fogC, 0.10);
          gBG.fill(red(c), green(c), blue(c), 255);
        }

        gBG.rect(0, y, W, step + 1);
        y += step;
      }
      gBG.pop();

      // radial fog overlay in separate pass but still in this task for speed
      if (mode === "radialFog" && y >= H) {
        gBG.push();
        gBG.noStroke();
        gBG.blendMode(MULTIPLY);
        var cx = W * 0.5, cy = H * 0.5;
        var rings = 44;
        for (let i = 0; i < rings; i++) {
          var t = i / (rings - 1);
          var rr = lerp(min(W, H) * 0.10, min(W, H) * 0.68, t);
          var a = 30 * pow(t, 1.6);
          var c = lerpColor(fogC, ink, 0.2);
          gBG.fill(red(c), green(c), blue(c), a * blend);
          gBG.ellipse(cx + rng.range(-8, 8), cy + rng.range(-8, 8), rr * 2, rr * 2);
        }
        gBG.pop();
      }

      return y >= H;
    }
  };
}

function makeTask_BG_Secondary(bp, pal, rng) {
  // gentle "map" lines / faint crosshatch in BG (slow build)
  let N = floor(2200 * rng.range(0.7, 1.3));
  let i = 0;

  // precompute style
  var c = lerpColor(pal.pick(rng.int(0, 4)), color(240), 0.7);
  var alpha = rng.range(10, 26);
  let sw = rng.range(0.6, 1.3);
  var mode = rng.pick(["flow", "waves", "microGrid"], [1.1, 0.9, 0.7]);

  // flow knobs
  let sc = bp.flowScale * rng.range(0.9, 1.5);
  let amp = bp.flowStrength * rng.range(0.4, 1.0);

  return {
    step: () => {
      gBG.push();
      gBG.blendMode(MULTIPLY);
      gBG.stroke(red(c), green(c), blue(c), alpha);
      gBG.strokeWeight(sw);
      gBG.noFill();

      let chunk = 60;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;

        var x = rng.range(0, W);
        var y = rng.range(0, H);

        if (mode === "flow") {
          let len = rng.range(14, 44);
          var a = flowAngle(x, y, sc, amp);
          let x2 = x + cos(a) * len;
          let y2 = y + sin(a) * len;
          gBG.line(x, y, x2, y2);
        } else if (mode === "waves") {
          var len = rng.range(10, 40);
          var a = sin((x * 0.012) + (y * 0.008) + rng.range(-1, 1)) * 1.2;
          var x2 = x + cos(a) * len;
          var y2 = y + sin(a) * len;
          gBG.line(x, y, x2, y2);
        } else {
          // microGrid
          if (rng.bool(0.5)) gBG.line(x, y, x + rng.range(8, 28), y);
          else gBG.line(x, y, x, y + rng.range(8, 28));
        }

        i++;
      }

      gBG.pop();
      return i >= N;
    }
  };
}

function makeTask_BG_Speckles(bp, pal, rng) {
  // faint ink speckles
  var N = floor(3200 * rng.range(0.65, 1.35));
  var i = 0;

  var c = lerpColor(pal.pick(rng.int(0, 4)), color(10), 0.8);
  let baseA = rng.range(8, 22);
  let sizeMin = rng.range(0.6, 1.2);
  let sizeMax = rng.range(1.4, 3.4);

  return {
    step: () => {
      gBG.push();
      gBG.noStroke();
      gBG.blendMode(MULTIPLY);

      var chunk = 120;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;

        var x = rng.range(0, W);
        var y = rng.range(0, H);
        var a = baseA * pow(rng.float(), 1.8);
        var r = lerp(sizeMin, sizeMax, pow(rng.float(), 2.6));

        gBG.fill(red(c), green(c), blue(c), a);
        gBG.circle(x, y, r);

        i++;
      }

      gBG.pop();
      return i >= N;
    }
  };
}

/* =========================================================
   Overlay / Finisher Tasks
   ========================================================= */

function makeTask_Overlay_Scratches(bp, pal, rng) {
  // top-level scratches + tiny thread lines (subtle)
  var N = floor(520 * rng.range(0.8, 1.4));
  var i = 0;

  var c = lerpColor(pal.ink(), color(255), 0.35);
  let a0 = rng.range(10, 24);
  var sw = bp.inkWeight * rng.range(0.35, 0.7);

  return {
    step: () => {
      gINK.push();
      gINK.blendMode(MULTIPLY);
      gINK.stroke(red(c), green(c), blue(c), a0);
      gINK.strokeWeight(sw);
      gINK.noFill();

      var chunk = 24;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;
        var x = rng.range(0, W);
        var y = rng.range(0, H);
        var len = rng.range(20, 120);
        let ang = rng.range(-PI, PI);

        // multi-segment scratch with slight jitter
        let seg = rng.int(2, 6);
        let px = x, py = y;
        for (let s = 0; s < seg; s++) {
          var t = (s + 1) / seg;
          let nx = x + cos(ang) * len * t + rng.range(-6, 6);
          let ny = y + sin(ang) * len * t + rng.range(-6, 6);
          gINK.line(px, py, nx, ny);
          px = nx; py = ny;
        }

        i++;
      }
      gINK.pop();
      return i >= N;
    }
  };
}

function makeTask_Overlay_Unify(bp, pal, rng) {
  // unify: subtle shadowing + edge emphasis
  var i = 0;
  let passes = 120;

  var ink = pal.ink();
  var alpha = rng.range(8, 18);

  return {
    step: () => {
      if (i >= passes) return true;

      gINK.push();
      gINK.blendMode(MULTIPLY);

      if (bp.shadowMode) {
        // soft shadow strokes across piece
        gINK.noFill();
        gINK.stroke(red(ink), green(ink), blue(ink), alpha);
        gINK.strokeWeight(bp.inkWeight * rng.range(0.4, 1.0));

        var n = 24;
        for (let k = 0; k < n; k++) {
          var x = rng.range(0, W);
          var y = rng.range(0, H);
          var len = rng.range(20, 80);
          var a = rng.range(-PI, PI);
          gINK.line(x, y, x + cos(a) * len, y + sin(a) * len);
        }
      }

      // edge emphasis
      gINK.noFill();
      gINK.stroke(0, 14);
      gINK.strokeWeight(2);
      gINK.rect(bp.margin * 0.6, bp.margin * 0.6, W - bp.margin * 1.2, H - bp.margin * 1.2, 22);

      gINK.pop();

      i++;
      return i >= passes;
    }
  };
}

/* =========================================================
   Shape Tasks — Rounded Plate
   ========================================================= */

function makeTask_Shape_Fill_RoundedPlate(p) {
  // fills are built as many translucent strokes (not a single fill)
  // precompute stroke parameters
  var steps = floor(140 * p.detail);
  var i = 0;

  var c1 = p.fillA;
  var c2 = p.fillB;

  // choose fill family from blueprint
  let fam = p.bp.fillFamily;

  // precompute jitter scale
  let jit = p.bp.inkWeight * 0.35;

  return {
    step: () => {
      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);

      gFILL.noStroke();

      var chunk = 10;
      for (let k = 0; k < chunk; k++) {
        if (i >= steps) break;

        var t = i / max(1, steps - 1);
        // soft gradient by layering small strips
        let localY = lerp(-p.h * 0.5, p.h * 0.5, t);
        var alpha = 40 * (0.5 + 0.5 * sin(t * PI));
        var c = lerpColor(c1, c2, smoothstep(0, 1, t));

        if (fam === "softGradient") {
          gFILL.fill(red(c), green(c), blue(c), alpha);
          roundedRectStrip(gFILL, -p.w * 0.5, localY - p.h / steps, p.w, p.h / steps * 2.3, p.r);
        } else if (fam === "banded") {
          var band = (floor(t * 8) / 7);
          let cc = lerpColor(c1, c2, band);
          gFILL.fill(red(cc), green(cc), blue(cc), alpha * 0.85);
          roundedRectStrip(gFILL, -p.w * 0.5, localY - p.h / steps, p.w, p.h / steps * 2.0, p.r);
        } else if (fam === "inkWash") {
          var n = noise(p.x * 0.01 + t * 2.2, p.y * 0.01 + t * 1.7);
          var cc = lerpColor(c1, c2, n);
          gFILL.fill(red(cc), green(cc), blue(cc), alpha * 0.9);
          roundedRectStrip(gFILL, -p.w * 0.5 + (n - 0.5) * jit * 8, localY - p.h / steps, p.w, p.h / steps * 2.5, p.r);
        } else if (fam === "cellShade") {
          var n = noise(p.x * 0.02 + t * 2.0, p.y * 0.02);
          let levels = 4;
          let q = floor(n * levels) / (levels - 1);
          var cc = lerpColor(c1, c2, q);
          gFILL.fill(red(cc), green(cc), blue(cc), alpha * 0.85);
          roundedRectStrip(gFILL, -p.w * 0.5, localY - p.h / steps, p.w, p.h / steps * 2.2, p.r);
        } else {
          // marble-ish: wavy modulation
          var n = noise((p.x + localY) * 0.01, (p.y - localY) * 0.01);
          let wav = sin((t * TAU * 3) + n * 4.0);
          var cc = lerpColor(c1, c2, 0.5 + 0.5 * wav);
          gFILL.fill(red(cc), green(cc), blue(cc), alpha * 0.75);
          roundedRectStrip(gFILL, -p.w * 0.5 + wav * jit * 5, localY - p.h / steps, p.w, p.h / steps * 2.4, p.r);
        }

        i++;
      }

      gFILL.pop();
      return i >= steps;
    }
  };
}

function makeTask_Shape_Outline_RoundedPlate(p) {
  // outline: drawn in segments to feel “plotted”
  let segs = 240;
  var i = 0;

  // style based on outlineStyle
  let style = p.bp.outlineStyle;
  let wob = (style === "wobbleFine" ? 0.9 : style === "wobbleBold" ? 2.2 : 0.0) * p.bp.inkWeight;

  var sw = p.outlineW;
  var ink = p.strokeC;

  return {
    step: () => {
      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);

      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), 210);
      gINK.strokeWeight(sw);

      // draw a piece of the rounded-rect perimeter each step
      var chunk = 6;
      for (let k = 0; k < chunk; k++) {
        if (i >= segs) break;

        let t0 = i / segs;
        let t1 = (i + 1) / segs;

        var a0 = t0 * TAU;
        let a1 = t1 * TAU;

        // param curve around rounded rect
        let P0 = rrPerimeterPoint(p.w, p.h, p.r, a0);
        let P1 = rrPerimeterPoint(p.w, p.h, p.r, a1);

        gINK.line(
          P0.x + noiseJitter(P0.x, P0.y, wob),
          P0.y + noiseJitter(P0.y, P0.x, wob),
          P1.x + noiseJitter(P1.x, P1.y, wob),
          P1.y + noiseJitter(P1.y, P1.x, wob)
        );

        i++;
      }

      // double outline option
      if (style === "double" && i >= segs) {
        gINK.strokeWeight(sw * 0.55);
        gINK.stroke(red(ink), green(ink), blue(ink), 120);
        gINK.rect(-p.w * 0.5 + 2, -p.h * 0.5 + 2, p.w - 4, p.h - 4, p.r * 0.92);
      }

      gINK.pop();
      return i >= segs;
    }
  };
}

function makeTask_Shape_InnerFrames(p) {
  let total = p.frameCount;
  let idx = 0;

  var ink = p.strokeC;
  var style = p.bp.outlineStyle;

  return {
    step: () => {
      if (idx >= total) return true;

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);

      let inset = p.inset * (idx + 1) * (0.9 + 0.2 * sin(idx * 2.3));
      var w = p.w - inset * 2;
      let h = p.h - inset * 2;
      var r = max(2, p.r - inset * 0.7);

      var alpha = 130 * pow(1 - idx / max(1, total - 1), 0.7);
      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), alpha);
      gINK.strokeWeight(p.outlineW * (0.55 + 0.25 * (idx % 2)));

      if (style === "clean" || style === "double") {
        gINK.rect(-w * 0.5, -h * 0.5, w, h, r);
      } else {
        // slightly wobbly frame: polyline approximation
        drawWobblyRoundedRect(gINK, w, h, r, p.bp.inkWeight * (style === "wobbleBold" ? 2.0 : 1.0));
      }

      gINK.pop();

      idx++;
      return idx >= total;
    }
  };
}

function makeTask_Shape_CornerOrbs(p) {
  var i = 0;
  let corners = [
    { x: -p.w * 0.5 + p.r, y: -p.h * 0.5 + p.r },
    { x:  p.w * 0.5 - p.r, y: -p.h * 0.5 + p.r },
    { x:  p.w * 0.5 - p.r, y:  p.h * 0.5 - p.r },
    { x: -p.w * 0.5 + p.r, y:  p.h * 0.5 - p.r }
  ];

  // precompute which corners
  let mask = [];
  for (let c = 0; c < 4; c++) mask.push(hashFloat(p.seed ^ (c * 1013) ^ 0x1234abcd, c) > 0.35);

  return {
    step: () => {
      if (i >= 4) return true;

      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);

      var c = corners[i];
      if (mask[i]) {
        var rr = p.r * 0.42;
        var cc = lerpColor(p.fillA, p.fillB, i / 3);
        gFILL.noStroke();
        gFILL.fill(red(cc), green(cc), blue(cc), 110);
        gFILL.circle(c.x, c.y, rr * 2);

        gINK.push();
        gINK.translate(p.x, p.y);
        gINK.rotate(p.rot);
        gINK.noFill();
        gINK.stroke(0, 180);
        gINK.strokeWeight(p.outlineW * 0.65);
        gINK.circle(c.x, c.y, rr * 2);
        gINK.pop();
      }

      gFILL.pop();

      i++;
      return i >= 4;
    }
  };
}

function makeTask_Shape_InteriorPattern(p) {
  // interior pattern is drawn as incremental strokes
  let motif = p.innerMotif;
  var i = 0;

  // pattern budget
  var N = floor(1200 * p.detail);

  // interior bounds
  let iw = p.w - p.inset * (p.frameCount + 1) * 1.4;
  let ih = p.h - p.inset * (p.frameCount + 1) * 1.4;
  let ir = max(2, p.r - p.inset * (p.frameCount + 1) * 0.9);

  // style
  var ink = p.strokeC;
  var alpha = 120;
  var sw = p.outlineW * 0.45;

  // flow
  var sc = p.bp.flowScale * 1.35;
  var amp = p.bp.flowStrength * 0.9;

  return {
    step: () => {
      if (i >= N) return true;

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);
      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), alpha);
      gINK.strokeWeight(sw);

      var chunk = 26;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;

        // pick a point inside rounded rect
        var x = (hashFloat(p.seed ^ 0xBEEF0001, i) - 0.5) * iw;
        var y = (hashFloat(p.seed ^ 0xBEEF0002, i) - 0.5) * ih;

        if (!pointInRoundedRect(x, y, iw, ih, ir)) { i++; continue; }

        if (motif === "hatch") {
          var a = flowAngle(x + p.x, y + p.y, sc, amp) + PI / 2;
          var len = lerp(10, 40, noise((x + p.x) * 0.02, (y + p.y) * 0.02));
          gINK.line(x, y, x + cos(a) * len, y + sin(a) * len);
        } else if (motif === "contours") {
          // contour rings: approximate by small arcs around center
          var ang = atan2(y, x);
          var rr = sqrt(x * x + y * y);
          var band = (floor(rr / 8) % 2 === 0) ? 1 : -1;
          var a = ang + band * 0.25;
          var len = 16 + 22 * noise(rr * 0.03, ang * 0.9);
          gINK.line(x, y, x + cos(a) * len, y + sin(a) * len);
        } else if (motif === "moire") {
          var a = sin((x * 0.09) + (y * 0.05)) * 1.4;
          var len = 18 + 26 * noise(x * 0.03 + 10, y * 0.03 + 10);
          gINK.line(x, y, x + cos(a) * len, y + sin(a) * len);
        } else if (motif === "spiral") {
          var ang = atan2(y, x) + rrSpiralTurn(x, y) * 0.45;
          var len = 12 + 18 * noise(x * 0.03, y * 0.03);
          gINK.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
        } else {
          // glyph: tiny curves + hooks
          var a = flowAngle(x + p.x, y + p.y, sc * 1.2, amp * 0.8);
          var len = 8 + 18 * noise(x * 0.05, y * 0.05);
          var x2 = x + cos(a) * len;
          var y2 = y + sin(a) * len;
          gINK.beginShape();
          gINK.vertex(x, y);
          gINK.quadraticVertex((x + x2) * 0.5 + sin(a) * 6, (y + y2) * 0.5 - cos(a) * 6, x2, y2);
          gINK.endShape();
        }

        i++;
      }

      gINK.pop();
      return i >= N;
    }
  };
}

/* =========================================================
   Shape Tasks — Tri Wedge
   ========================================================= */

function makeTask_Shape_Fill_TriWedge(p) {
  var i = 0;
  var steps = floor(150 * p.detail);

  var fam = p.bp.fillFamily;
  var c1 = p.fillA;
  var c2 = p.fillB;

  return {
    step: () => {
      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);
      gFILL.noStroke();

      var chunk = 10;
      for (let k = 0; k < chunk; k++) {
        if (i >= steps) break;
        var t = i / max(1, steps - 1);

        // triangle points (slightly twisted)
        let A = createVector(-p.r1 * 0.55, p.r2 * 0.55);
        let B = createVector(0, -p.r1 * 0.65);
        let C = createVector(p.r2 * 0.62, p.r1 * 0.58);
        B.x += p.twist * p.r1;

        // fill by drawing inset triangles
        var inset = lerp(0, min(p.r1, p.r2) * 0.42, t);
        var a = 55 * (0.65 + 0.35 * sin(t * PI));
        let col;

        if (fam === "softGradient") col = lerpColor(c1, c2, smoothstep(0, 1, t));
        else if (fam === "banded") {
          var band = floor(t * 7) / 6;
          col = lerpColor(c1, c2, band);
        } else if (fam === "inkWash") {
          var n = noise((p.x + t * 100) * 0.01, (p.y - t * 70) * 0.01);
          col = lerpColor(c1, c2, n);
        } else if (fam === "cellShade") {
          var n = noise((p.x + t * 60) * 0.02, (p.y + t * 60) * 0.02);
          let lv = 4;
          var q = floor(n * lv) / (lv - 1);
          col = lerpColor(c1, c2, q);
        } else {
          var n = noise((p.x + t * 90) * 0.01, (p.y + t * 20) * 0.01);
          var wav = sin(t * TAU * 2 + n * 4);
          col = lerpColor(c1, c2, 0.5 + 0.5 * wav);
        }

        gFILL.fill(red(col), green(col), blue(col), a);

        let Ai = p5.Vector.lerp(A, createVector(0, 0), inset / max(1, p.r1));
        let Bi = p5.Vector.lerp(B, createVector(0, 0), inset / max(1, p.r1));
        let Ci = p5.Vector.lerp(C, createVector(0, 0), inset / max(1, p.r1));

        gFILL.triangle(Ai.x, Ai.y, Bi.x, Bi.y, Ci.x, Ci.y);

        i++;
      }
      gFILL.pop();

      return i >= steps;
    }
  };
}

function makeTask_Shape_Outline_TriWedge(p) {
  var i = 0;
  var segs = 180;

  var ink = p.strokeC;
  var wob = (p.bp.outlineStyle.includes("wobble") ? (p.bp.outlineStyle === "wobbleBold" ? 2.2 : 1.1) : 0) * p.bp.inkWeight;

  // triangle points
  var A = createVector(-p.r1 * 0.55, p.r2 * 0.55);
  var B = createVector(0, -p.r1 * 0.65);
  var C = createVector(p.r2 * 0.62, p.r1 * 0.58);
  B.x += p.twist * p.r1;

  let poly = [A, B, C, A];

  return {
    step: () => {
      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);
      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), 210);
      gINK.strokeWeight(p.outlineW);

      var chunk = 8;
      for (let k = 0; k < chunk; k++) {
        if (i >= segs) break;

        var t = i / segs;
        // edge selection
        var e = floor(t * 3);
        let lt = (t * 3) - e;

        var P0 = p5.Vector.lerp(poly[e], poly[e + 1], lt);
        var P1 = p5.Vector.lerp(poly[e], poly[e + 1], min(1, lt + 1 / (segs / 3)));

        gINK.line(
          P0.x + noiseJitter(P0.x, P0.y, wob),
          P0.y + noiseJitter(P0.y, P0.x, wob),
          P1.x + noiseJitter(P1.x, P1.y, wob),
          P1.y + noiseJitter(P1.y, P1.x, wob)
        );

        i++;
      }

      gINK.pop();
      return i >= segs;
    }
  };
}

function makeTask_Shape_Bands_TriWedge(p) {
  // contour bands inside triangle
  var i = 0;
  var N = floor(p.bandCount * 18 * p.detail);

  var ink = p.strokeC;
  var sw = p.outlineW * 0.38;
  var alpha = 120;

  // triangle base points
  var A = createVector(-p.r1 * 0.55, p.r2 * 0.55);
  var B = createVector(0, -p.r1 * 0.65);
  var C = createVector(p.r2 * 0.62, p.r1 * 0.58);
  B.x += p.twist * p.r1;

  return {
    step: () => {
      if (i >= N) return true;

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);
      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), alpha);
      gINK.strokeWeight(sw);

      var chunk = 28;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;

        // pick a barycentric point, draw small curve segment
        let u = hashFloat(p.seed ^ 0x77770001, i);
        let v = hashFloat(p.seed ^ 0x77770002, i);
        if (u + v > 1) { u = 1 - u; v = 1 - v; }
        var w = 1 - u - v;

        let P = createVector(
          A.x * u + B.x * v + C.x * w,
          A.y * u + B.y * v + C.y * w
        );

        var ang = atan2(P.y, P.x) + sin((u + v) * 6.0) * 0.6;
        var len = 10 + 26 * noise(P.x * 0.03, P.y * 0.03);
        let Q = createVector(P.x + cos(ang) * len, P.y + sin(ang) * len);

        gINK.beginShape();
        gINK.vertex(P.x, P.y);
        gINK.quadraticVertex((P.x + Q.x) * 0.5 + sin(ang) * 6, (P.y + Q.y) * 0.5 - cos(ang) * 6, Q.x, Q.y);
        gINK.endShape();

        i++;
      }

      gINK.pop();
      return i >= N;
    }
  };
}

function makeTask_Shape_Eye_TriWedge(p) {
  // “eye” motif: ellipse + pupil + eyelid arcs
  let stage = 0;
  var ink = p.strokeC;

  // precompute eye position
  let ex = 0;
  let ey = p.r1 * 0.08;
  let erx = min(p.r1, p.r2) * p.eyeScale * 1.2;
  let ery = erx * 0.65;

  return {
    step: () => {
      if (stage >= 5) return true;

      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);

      if (stage === 0) {
        // sclera
        gFILL.noStroke();
        var c = lerpColor(p.fillA, color(255), 0.55);
        gFILL.fill(red(c), green(c), blue(c), 140);
        gFILL.ellipse(ex, ey, erx * 2, ery * 2);
      } else if (stage === 1) {
        // iris
        gFILL.noStroke();
        var c = lerpColor(p.fillB, color(0), 0.25);
        gFILL.fill(red(c), green(c), blue(c), 120);
        gFILL.ellipse(ex, ey, erx * 1.15, ery * 1.15);
      } else if (stage === 2) {
        // pupil
        gFILL.noStroke();
        gFILL.fill(0, 160);
        gFILL.ellipse(ex + erx * 0.1, ey, erx * 0.45, ery * 0.55);
      } else if (stage === 3) {
        // outline
        gINK.noFill();
        gINK.stroke(red(ink), green(ink), blue(ink), 220);
        gINK.strokeWeight(p.outlineW * 0.8);
        gINK.ellipse(ex, ey, erx * 2, ery * 2);
      } else {
        // eyelid arcs
        gINK.noFill();
        gINK.stroke(red(ink), green(ink), blue(ink), 170);
        gINK.strokeWeight(p.outlineW * 0.55);
        gINK.arc(ex, ey, erx * 2.2, ery * 2.2, PI * 1.05, PI * 1.95);
        gINK.arc(ex, ey, erx * 2.2, ery * 2.2, PI * 0.05, PI * 0.95);
      }

      gFILL.pop();
      gINK.pop();

      stage++;
      return stage >= 5;
    }
  };
}

/* =========================================================
   Shape Tasks — Orb Lens
   ========================================================= */

function makeTask_Shape_Fill_OrbLens(p) {
  var i = 0;
  var steps = floor(170 * p.detail);
  var fam = p.bp.fillFamily;

  return {
    step: () => {
      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);

      gFILL.noStroke();

      var chunk = 10;
      for (let k = 0; k < chunk; k++) {
        if (i >= steps) break;

        var t = i / max(1, steps - 1);
        var rr = lerp(1.0, 0.06, t);

        var a = 55 * (0.6 + 0.4 * sin(t * PI));
        var col;

        if (fam === "softGradient") col = lerpColor(p.fillA, p.fillB, smoothstep(0, 1, t));
        else if (fam === "banded") col = lerpColor(p.fillA, p.fillB, floor(t * 7) / 6);
        else if (fam === "inkWash") col = lerpColor(p.fillA, p.fillB, noise((p.x + t * 180) * 0.01, (p.y - t * 90) * 0.01));
        else if (fam === "cellShade") {
          var n = noise((p.x + t * 120) * 0.02, (p.y + t * 120) * 0.02);
          var lv = 5;
          col = lerpColor(p.fillA, p.fillB, floor(n * lv) / (lv - 1));
        } else {
          var n = noise((p.x + t * 90) * 0.01, (p.y + t * 30) * 0.01);
          col = lerpColor(p.fillA, p.fillB, 0.5 + 0.5 * sin(t * TAU * 2 + n * 4));
        }

        gFILL.fill(red(col), green(col), blue(col), a);

        // draw concentric ellipses for fill
        gFILL.ellipse(0, 0, p.rx * 2 * rr, p.ry * 2 * rr);

        i++;
      }

      gFILL.pop();
      return i >= steps;
    }
  };
}

function makeTask_Shape_Outline_OrbLens(p) {
  var stage = 0;
  var ink = p.strokeC;

  return {
    step: () => {
      if (stage >= 2) return true;

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);
      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), stage === 0 ? 220 : 120);
      gINK.strokeWeight(stage === 0 ? p.outlineW : p.outlineW * 0.6);

      gINK.ellipse(0, 0, p.rx * 2, p.ry * 2);

      gINK.pop();

      stage++;
      return stage >= 2;
    }
  };
}

function makeTask_Shape_Rings_OrbLens(p) {
  var i = 0;
  var N = p.rings;
  var ink = p.strokeC;

  // ring slant
  let sl = p.slant;

  return {
    step: () => {
      if (i >= N) return true;

      gINK.push();
      gINK.translate(p.x, p.y);
      gINK.rotate(p.rot);

      gINK.noFill();
      gINK.stroke(red(ink), green(ink), blue(ink), 120);
      gINK.strokeWeight(p.outlineW * 0.35);

      // ring (arc) per step
      var t = i / max(1, N - 1);
      var rr = lerp(0.18, 1.0, t);
      var aa = lerp(0.2, 0.65, t);

      let start = PI + sl * 0.8 + aa;
      let end = TAU + sl * 0.8 - aa;

      gINK.arc(0, 0, p.rx * 2 * rr, p.ry * 2 * rr, start, end);

      gINK.pop();

      i++;
      return i >= N;
    }
  };
}

function makeTask_Shape_Highlight_OrbLens(p) {
  var i = 0;
  var N = floor(220 * p.detail);

  var c = lerpColor(color(255), p.fillB, 0.35);

  return {
    step: () => {
      if (i >= N) return true;

      gFILL.push();
      gFILL.translate(p.x, p.y);
      gFILL.rotate(p.rot);

      gFILL.noStroke();

      var chunk = 20;
      for (let k = 0; k < chunk; k++) {
        if (i >= N) break;

        var t = i / max(1, N - 1);
        var a = 18 * (1 - t);
        var x = lerp(-p.rx * 0.28, p.rx * 0.12, t);
        var y = lerp(-p.ry * 0.38, -p.ry * 0.12, t);
        let rx = lerp(p.rx * 0.48, p.rx * 0.12, t);
        let ry = lerp(p.ry * 0.34, p.ry * 0.08, t);

        gFILL.fill(red(c), green(c), blue(c), a);
        gFILL.ellipse(x, y, rx, ry);

        i++;
      }

      gFILL.pop();
      return i >= N;
    }
  };
}

function makeTask_Shape_Notch_OrbLens(p) {
  // small cut or “bite”
  var stage = 0;
